mapper.select:
SELECT * FROM ftp_download_task
WHERE deleted = 0 AND id > #{afterId}
  AND status IN ('QUEUED', 'CONNECTING', 'DOWNLOADING', 'PAUSING', 'DELETING', 'RETRY_WAIT', 'VERIFYING')
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE ftp_download_task
SET deleted = id, revision = revision + 1, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND task_uuid = #{taskUuid}
  AND user_id = #{userId} AND deleted = 0 AND revision = #{expectedRevision}
